/*
 * A006928  a(n) = length of (n+1)st run, with initial terms 1, 2.
 * https://oeis.org/A006928
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(1) = 1, a(n) = A000002(n+1) for n > 1, where A000002 is the
 *            Kolakoski sequence 1,2,2,1,1,2,... generated by its own run
 *            lengths
 * Range:     u8 n <= 108, u16 n <= 108, u32 n <= 108, u64 n <= 108,
 *            u128 n <= 108, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static unsigned char *kol = NULL;
static idx_t kol_len = 0;

static void kol_build(idx_t need) {
    idx_t cap, len, j;
    unsigned char *s;
    if (kol != NULL && kol_len >= need) return;
    cap = need + 4;
    if (cap < 8) cap = 8;
    s = (unsigned char *)malloc((size_t)(cap + 1));
    s[0] = 0;
    s[1] = 1; s[2] = 2; s[3] = 2;
    len = 3;
    j = 3;
    while (len < need) {
        unsigned char v = (unsigned char)(3 - s[len]);
        unsigned char r = s[j];
        unsigned char t;
        for (t = 0; t < r && len < cap; t++) {
            s[++len] = v;
        }
        j++;
    }
    free(kol);
    kol = s;
    kol_len = len;
}

seq_t a(idx_t n) {
    if (n == 1) return (seq_t)1;
    kol_build(n + 1);
    return (seq_t)kol[n + 1];
}
